use std::process;

// Help texts (exact)
const MAIN_HELP: &str = "svgbob 0.7.6\nSvgBobRus is an ascii to svg converter\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]\n\nFLAGS:\n    -h, --help       Prints help information\n    -s               parse an inline string\n    -V, --version    Prints version information\n\nOPTIONS:\n        --background <background>        backdrop background will be filled with this color (default: 'white')\n        --fill-color <fill-color>        solid shapes will be filled with this color (default: 'black')\n        --font-family <font-family>      text will be rendered with this font (default: 'arial')\n        --font-size <font-size>          text will be rendered with this font size (default: 14)\n    -o, --output <output>                where to write svg output [default: STDOUT]\n        --scale <scale>                  scale the entire svg (dimensions, font size, stroke width) by this factor\n                                         (default: 1)\n        --stroke-color <stroke-color>    stroke color for all lines (default: 'black')\n        --stroke-width <stroke-width>    stroke width for all lines (default: 2)\n\nARGS:\n    <input>    svgbob text file or inline string to parse [default: STDIN]\n\nSUBCOMMANDS:\n    build    Batch convert files to svg.\n    help     Prints this message or the help of the given subcommand(s)\n";
const MAIN_VERSION: &str = "svgbob 0.7.6\n";
const BUILD_HELP: &str = "executable-build 0.0.1\nBatch convert files to svg.\n\nUSAGE:\n    executable build [OPTIONS]\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nOPTIONS:\n    -i, --input <input>      set input file pattern like: *.bob or dir/*.bob\n    -o, --outdir <outdir>    set dir of svg files\n";
const BUILD_VERSION: &str = "executable-build 0.0.1\n";
const HELP_HELP: &str = "executable-help \nPrints this message or the help of the given subcommand(s)\n\nUSAGE:\n    executable help [subcommand]...\n\nARGS:\n    <subcommand>...    The subcommand whose help message to display\n";

fn main() {
    let args: Vec<String> = env::args().collect();
    // args[0] is prog name, rest are actual args
    let prog_args = &args[1..];
    std::process::exit(run(prog_args));
}

fn run(args: &[String]) -> i32 {
    // First, check if this is build or help subcommand invocation?
    // We need to parse main args up to subcommand, handling help/version precedence etc.
    // Approach: manual parsing mimicking clap2.
    parse_main(args)
}

fn print_err_and_exit(code: i32, msg: &str) -> i32 {
    eprint!("{}", msg);
    code
}

// Definition order for usage: background, fill-color, font-family, font-size, -s, output, scale, stroke-color, stroke-width
fn main_usage_specific(used: &MainUsed) -> String {
    let mut parts: Vec<String> = Vec::new();
    if used.background { parts.push("--background <background>".to_string()); }
    if used.fill_color { parts.push("--fill-color <fill-color>".to_string()); }
    if used.font_family { parts.push("--font-family <font-family>".to_string()); }
    if used.font_size { parts.push("--font-size <font-size>".to_string()); }
    if used.s_flag { parts.push("-s".to_string()); }
    if used.output { parts.push("--output <output>".to_string()); }
    if used.scale { parts.push("--scale <scale>".to_string()); }
    if used.stroke_color { parts.push("--stroke-color <stroke-color>".to_string()); }
    if used.stroke_width { parts.push("--stroke-width <stroke-width>".to_string()); }
    if parts.is_empty() {
        "executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]".to_string()
    } else {
        format!("executable {}", parts.join(" "))
    }
}

#[derive(Default, Clone)]
struct MainUsed {
    background: bool,
    fill_color: bool,
    font_family: bool,
    font_size: bool,
    s_flag: bool,
    output: bool,
    scale: bool,
    stroke_color: bool,
    stroke_width: bool,
}

#[derive(Default)]
struct MainOpts {
    background: Option<String>,
    fill_color: Option<String>,
    font_family: Option<String>,
    font_size: Option<String>,
    output: Option<String>,
    scale: Option<String>,
    stroke_color: Option<String>,
    stroke_width: Option<String>,
    s_flag: bool,
    input: Option<String>, // positional input (file or inline string)
}

fn parse_main(args: &[String]) -> i32 {
    // We need to handle help/version, subcommands, options, positionals.
    // Steps:
    // - Iterate through args, handling --, -, combined shorts, longs, positionals, subcommands.
    // - Track used options for usage, duplicates, missing values, unknown, extra positionals.
    // - Help/version: if encountered, we need to decide precedence vs prior errors.
    //   From observations:
    //   - Unknown/extra errors before help win over help (help ignored).
    //   - Duplicate/missing errors before help are ignored (help wins).
    //   So we need to process in order, reporting unknown/extra immediately, but deferring duplicate/missing until after, unless help/version encountered first?
    //   Actually for duplicate before help, help wins, so duplicate must be deferred.
    //   For missing value where next is help flag, help wins (not missing).
    //   For extra before help, extra wins (help ignored). So extra is immediate.
    //   So: unknown/extra are immediate; duplicate/missing are deferred until after parsing (and after help check).
    // - Also need to handle subcommands: when we encounter "build" or "help" as positional (not after --, not as option value), treat as subcommand.
    //   But what about "build" after --? It gives special subcommand error with suggestion, not treated as input. So "build"/"help" after -- still trigger subcommand error (not input). While other positionals after -- are inputs.
    //   And what about "build" as value for -s? E.g., "-s build" => build is subcommand, not input. So subcommand takes precedence over input for -s? Actually "-s build" has -s flag and "build" positional. Normally "build" would be input (inline string), but it's treated as subcommand instead, and -s ends up with no input (but since subcommand present, we run subcommand, ignoring -s missing input panic). Good.
    //   Similarly, "hi build" (input + subcommand) => subcommand wins, input ignored.
    //   So subcommand detection happens during parsing: when we see "build"/"help" as positional (whether after -- or not? After --, other positionals are inputs, but build/help still trigger subcommand error, not input. Hmm need to handle.)
    //
    // Let's implement parsing loop.

    let mut opts = MainOpts::default();
    let mut used = MainUsed::default();
    // Track duplicates: need to detect second occurrence
    let mut seen_background = false;
    let mut seen_fill = false;
    let mut seen_font_family = false;
    let mut seen_font_size = false;
    let mut seen_output = false;
    let mut seen_scale = false;
    let mut seen_stroke_color = false;
    let mut seen_stroke_width = false;
    let mut seen_s = false;
