// Build parsing
fn parse_build(args: &[String]) -> i32 {
    // Similar to main but simpler: options -i/--input, -o/--outdir, flags -h/--help, -V/--version, no positionals.
    // Handling for --, -, combined shorts, etc. similar to main.
    // For build, "-" as arg? Is "-" treated as positional (unexpected) or as value? For ["build", "-"]? Likely "Found argument '-'..." with USAGE build [OPTIONS]. Good. For ["build", "-i", "-"]? "-" as value for -i (allowed, since "-" is not flag). Good. Similarly for -o.
    // For ["build", "--", "-i"]? After --, "-i" is positional (unexpected), error about '-i'. Good (we saw).
    // For help/version: immediate, first wins. For ["build", "-h", "-V"], help wins. Good.
    // For unknown/extra immediate, duplicate/missing deferred, help wins over duplicate/missing, unknown/extra win over help if before help.
    // USAGE for build errors: "executable build [OPTIONS]" for generic (no valid options before error), or "executable build --input <input>" / "--outdir <outdir>" / both (in definition order input then outdir) for specific.
    // Definition order: input, outdir.

    let mut seen_input = false;
    let mut seen_outdir = false;
    let mut used_input = false;
    let mut used_outdir = false;
    let mut opt_input: Option<String> = None;
    let mut opt_outdir: Option<String> = None;
    let mut dup_err: Option<String> = None;
    let mut miss_err: Option<String> = None;
    let mut idx = 0;
    let mut end_opts = false;

    let build_usage = |u_in: bool, u_out: bool| -> String {
        if !u_in && !u_out {
            "executable build [OPTIONS]".to_string()
        } else if u_in && !u_out {
            "executable build --input <input>".to_string()
        } else if !u_in && u_out {
            "executable build --outdir <outdir>".to_string()
        } else {
            "executable build --input <input> --outdir <outdir>".to_string()
        }
    };

    while idx < args.len() {
        let arg = &args[idx];
        if end_opts {
            // All remaining are positionals (unexpected, since build has no positionals)
            let usage = build_usage(used_input, used_outdir);
            let msg = format!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {}\n\nFor more information try --help\n", arg, usage);
            eprint!("{}", msg);
            return 1;
        } else {
            if arg == "--" {
                end_opts = true;
                idx += 1;
                continue;
            } else if arg == "-" {
                // Positional "-" (unexpected)
                let usage = build_usage(used_input, used_outdir);
                let msg = format!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {}\n\nFor more information try --help\n", arg, usage);
                eprint!("{}", msg);
                return 1;
            } else if arg.starts_with("--") {
                let (name, val_opt) = if let Some(eq) = arg.find('=') {
                    (&arg[..eq], Some(arg[eq+1..].to_string()))
                } else {
                    (arg.as_str(), None)
                };
                match name {
                    "--help" => {
                        print!("{}", BUILD_HELP);
                        return 0;
                    },
                    "--version" => {
                        print!("{}", BUILD_VERSION);
                        return 0;
                    },
                    "--input" | "--outdir" => {
                        let display = if name == "--input" { "--input <input>" } else { "--outdir <outdir>" };
                        let already = if name == "--input" { seen_input } else { seen_outdir };
                        if already {
                            if dup_err.is_none() {
                                dup_err = Some(display.to_string());
                            }
                        } else {
                            if name == "--input" { seen_input = true; used_input = true; } else { seen_outdir = true; used_outdir = true; }
                        }
                        if let Some(v) = val_opt {
                            if !already {
                                if name == "--input" { opt_input = Some(v); } else { opt_outdir = Some(v); }
                            }
                            idx += 1;
