                        } else {
                            if idx + 1 >= args.len() {
                                if miss_err.is_none() { miss_err = Some(display.to_string()); }
                                idx += 1;
                                continue;
                            } else {
                                let nxt = &args[idx+1];
                                if nxt == "--" {
                                    if miss_err.is_none() { miss_err = Some(display.to_string()); }
                                    idx += 1;
                                    continue;
                                } else if nxt == "-" {
                                    if !already {
                                        if name == "--input" { opt_input = Some(nxt.clone()); } else { opt_outdir = Some(nxt.clone()); }
                                    }
                                    idx += 2;
                                    continue;
                                } else if nxt.starts_with("-") {
                                    if is_build_unknown_arg(nxt) {
                                        idx += 1;
                                        continue;
                                    } else {
                                        if miss_err.is_none() { miss_err = Some(display.to_string()); }
                                        idx += 1;
                                        continue;
                                    }
                                } else {
                                    if !already {
                                        if name == "--input" { opt_input = Some(nxt.clone()); } else { opt_outdir = Some(nxt.clone()); }
                                    }
                                    idx += 2;
                                    continue;
