fn trimmed_len(line: &[char]) -> usize {
    let mut len = line.len();
    while len > 0 {
        let c = line[len-1];
        if c == ' ' || c == '\t' || c == '\r' {
            len -= 1;
        } else {
            break;
        }
    }
    len
}

fn escape_xml(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(c),
        }
    }
    out
}
