                    if arg.ends_with('o') && idx+1 < args.len() && args[idx+1] == "-" {
                        // Check if this 'o' is indeed an option expecting value (not part of attached value? But if arg ends with 'o', it means 'o' is last char, no rest, so expects next arg. Good. Unless arg is "-o" with unknown before? No, if arg contains unknown before 'o', we would have already errored on unknown before reaching 'o'. Good. So this 'o' is valid.
                        // Determine if duplicate: if seen_out was true before this arg? We need prev. For now, check opt_out.is_none() and dup handling as before.
                        let is_dup = dup_err.as_ref().map(|s| s == "--output <output>").unwrap_or(false);
                        if !is_dup && opt_out.is_none() {
                            opt_out = Some("-".to_string());
                        }
                        idx += 2;
                    } else {
                        idx += 1;
                    }
                }
                continue;
            } else {
                // Positional (does not start with '-')
                if arg == "build" || arg == "help" {
                    // Subcommand
                    // Collect remaining args after subcommand
                    let sub_args = &args[idx+1..];
                    if arg == "build" {
                        return parse_build(sub_args);
                    } else { // help
                        return parse_help(sub_args);
                    }
                } else {
                    if input_val.is_none() {
                        input_val = Some(arg.clone());
                    } else {
                        let usage = main_usage_specific(&used_main);
                        let msg = format!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {}\n\nFor more information try --help\n", arg, usage);
                        eprint!("{}", msg);
                        return 1;
                    }
                    idx += 1;
                    continue;
                }
            }
        }
    }

    // After loop, check deferred duplicates, then missings
    if let Some(dup_display) = dup_err {
        let usage = main_usage_specific(&used_main);
        let msg = if dup_display == "'-s'" {
            format!("error: The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {}\n\nFor more information try --help\n", dup_display, usage)
        } else {
            format!("error: The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {}\n\nFor more information try --help\n", dup_display, usage)
        };
        eprint!("{}", msg);
        return 1;
    }
    if let Some(miss_display) = miss_err {
        let usage = main_usage_specific(&used_main);
        let msg = format!("error: The argument '{}' requires a value but none was supplied\n\nUSAGE:\n    {}\n\nFor more information try --help\n", miss_display, usage);
        eprint!("{}", msg);
        return 1;
    }

    // No errors, proceed to main logic
    // Handle -s without input: panic
    if seen_s_flag && input_val.is_none() {
        // Panic at crates/svgbob_cli/src/main.rs:84:38
        panic_no_input();
        return 101; // unreachable, panic exits 101
    }

    // Parse numeric options
    // font-size: parse as u64, on error print "Illegal value for argument font-size: {e}" and exit 1
    // Note: need to use Rust's parse error messages exactly. For u64, errors are: "cannot parse integer from empty string", "invalid digit found in string", "number too large to fit in target type"
    // For f32, errors: "cannot parse float from empty string", "invalid float literal"
    // How to get these messages? By calling .parse::<u64>() and .parse::<f32>() and using e.to_string().
    // Good.

    let font_size_val: Option<u64> = if let Some(ref s) = opt_fsize {
        match s.parse::<u64>() {
            Ok(v) => Some(v),
            Err(e) => {
                eprint!("Illegal value for argument font-size: {}\n", e);
                return 1;
            }
        }
    } else { None };

    let stroke_width_val: Option<f32> = if let Some(ref s) = opt_swidth {
        match s.parse::<f32>() {
            Ok(v) => Some(v),
            Err(e) => {
                eprint!("Illegal value for argument stroke-width: {}\n", e);
                return 1;
            }
        }
    } else { None };

    let scale_val: Option<f32> = if let Some(ref s) = opt_scale {
        match s.parse::<f32>() {
            Ok(v) => Some(v),
            Err(e) => {
                eprint!("Illegal value for argument scale: {}\n", e);
                return 1;
            }
        }
    } else { None };

    // Read input
    let input_content: String;
    if seen_s_flag {
        // Inline string: input_val is Some (since we checked None above, it must be Some)
        input_content = input_val.clone().unwrap();
    } else if let Some(ref path) = input_val {
        // File path: try to open
        // On open error (NotFound, PermissionDenied, etc.), print "Failed to open input file {path}: {e}" and exit 1. But what about other errors? For directory, open succeeds but read fails with IsADirectory, which should panic (not print). How to distinguish? In Rust, File::open on directory succeeds (on Linux), then read_to_string fails with IsADirectory. So we should do File::open first, handle open errors (print and exit 1), then read_to_string, handle read errors: if InvalidData or IsADirectory (or other read errors?), panic with appropriate message at 88:44.
        // What about PermissionDenied on open? That's open error, print and exit 1 (as observed). Good.
        // What about NotFound on open? Print and exit 1. Good.
        // For read errors: InvalidData (binary file) => panic at 88:44 with "Error { kind: InvalidData, message: \"stream did not contain valid UTF-8\" }". IsADirectory (directory) => panic at 88:44 with "Os { code: 21, kind: IsADirectory, message: \"Is a directory\" }". What about other read errors (e.g., PermissionDenied during read? Unlikely, since open already succeeded. Interrupted? etc.)? Probably also panic with same location but different error display. Good. So for any read error (after successful open), panic.
        // Implement: match fs::File::open(path) { Err(e) => { eprint!("Failed to open input file {}: {}\n", path, e); return 1; }, Ok(mut f) => { let mut s = String::new(); match f.read_to_string(&mut s) { Err(e) => { panic_read_file(e); return 101; }, Ok(_) => { input_content = s; } } } }
        // Note: e.to_string() for io::Error gives "No such file or directory (os error 2)", "Permission denied (os error 13)", etc. Good. For read errors, panic message is "called `Result::unwrap()` on an `Err` value: {e:?}"? Actually panic message for Result::unwrap on Err shows Debug of error, not Display. For InvalidData, Debug is "Error { kind: InvalidData, message: \"stream did not contain valid UTF-8\" }". For IsADirectory, Debug is "Os { code: 21, kind: IsADirectory, message: \"Is a directory\" }". Good. So in panic message, we need Debug, not Display. Good. We'll implement panic_read_file to print with Debug.
        match fs::File::open(path) {
            Err(e) => {
                eprint!("Failed to open input file {}: {}\n", path, e);
                return 1;
            },
            Ok(mut f) => {
                let mut s = String::new();
                match f.read_to_string(&mut s) {
                    Err(e) => {
                        panic_read_file(e);
                        return 101;
                    },
                    Ok(_) => {
                        input_content = s;
                    }
                }
            }
        }
    } else {
        // No input, read from stdin
        // On read error (InvalidData for binary stdin), panic at 105:46 with same Debug. What about other stdin errors? Probably also panic. Good.
        // How to read stdin as UTF-8? Use io::read_to_string(io::stdin())? That returns Result<String, io::Error> with InvalidData for binary. Good.
        // But what about stdin being empty? Then input_content = "" (empty). Good.
        let mut s = String::new();
        match io::stdin().read_to_string(&mut s) {
            Err(e) => {
                panic_read_stdin(e);
                return 101;
            },
            Ok(_) => {
                input_content = s;
            }
        }
    }

    // Generate SVG
    let bg = opt_bg.as_deref().unwrap_or("white");
    let fill = opt_fill.as_deref().unwrap_or("black");
    let stroke = opt_scolor.as_deref().unwrap_or("black");
    let font_fam = opt_ffam.as_deref().unwrap_or("arial"); // Note: help says default 'arial', but style shows "Iosevka Fixed, monospace" as default? Wait help says default 'arial', but actual style default is "Iosevka Fixed, monospace" (as seen in outputs). Good. So when font-family not provided, use "Iosevka Fixed, monospace" (not "arial"). The help text is misleading (says 'arial', but actual default is different). Good. Similarly for other defaults: background 'white', fill 'black', stroke 'black', font-size 14, stroke-width 2, scale 1. Those match help. Only font-family mismatches: help says 'arial', actual is 'Iosevka Fixed, monospace'. Good. Must replicate actual, not help.
    // Actually check: when --font-family not provided, style shows "Iosevka Fixed, monospace". When provided (e.g., "courier"), style shows "courier". Good. So default is "Iosevka Fixed, monospace".
    // Similarly, check other defaults: background white, fill black, stroke black, font-size 14, stroke-width 2, scale 1. Good.

    let font_size = font_size_val.unwrap_or(14);
    let stroke_width = stroke_width_val.unwrap_or(2.0);
    let scale = scale_val.unwrap_or(1.0);
    // Note: font_family default handling: if not provided, use "Iosevka Fixed, monospace", else use provided (even if empty? For empty, style shows "font-family: ;" (empty). Good. So if provided as empty string, use empty, not default. Good. Our opt_ffam is Some("") for empty, so use "". Good. Similarly for bg, fill, stroke: if provided as empty, use empty (style shows "fill: ;"). Good.

    let svg = generate_svg(&input_content, bg, fill, stroke, font_fam, font_size, stroke_width, scale);

    // Write output
    if let Some(ref out_path) = opt_out {
        // Try to write to file. On error, print "Failed to write to output file {path}: {e}" and exit 2. Good. Note exit code 2 (not 1) for write errors. Good.
        match fs::write(out_path, svg) {
            Err(e) => {
                eprint!("Failed to write to output file {}: {}\n", out_path, e);
                return 2;
            },
            Ok(_) => {
                return 0;
            }
        }
    } else {
        // Write to stdout
        print!("{}", svg);
        return 0;
    }
}

fn is_main_unknown_arg(arg: &str) -> bool {
    if arg == "--" || arg == "-" {
        return false; // Not unknown, handled separately
    }
    if arg.starts_with("--") {
        let name = if let Some(eq) = arg.find('=') { &arg[..eq] } else { arg };
        match name {
            "--help" | "--version" | "--background" | "--fill-color" | "--font-family" | "--font-size" | "--output" | "--scale" | "--stroke-color" | "--stroke-width" => false,
            _ => true,
        }
    } else if arg.starts_with("-") && arg.len() > 1 {
        // Short, check each char: if any unknown, return true? Or only first? For ["--background", "-sfoo"]? "-sfoo" contains unknown 'f', so unknown. Good. For ["--background", "-oout"]? "-oout" is -o with value "out" (all known, since 'o' takes value, rest is value, not flags). How to determine? Iterate chars: first 'o' (takes value, rest is value, so fully known, return false). Good. For "-so" (s + o, where o expects next arg): chars 's' (known), 'o' (takes value, no rest, expects next arg, so fully known). Good. For "-ss" (s + s): both known. Good. For "-sh" (s + h): both known. Good. For "-x": 'x' unknown => true. Good. For "-s=hi": chars 's' (known), '=' (unknown) => true. Good.
        let chars: Vec<char> = arg[1..].chars().collect();
        let mut idx = 0;
        while idx < chars.len() {
            let c = chars[idx];
            match c {
                'h' | 'V' | 's' => { idx += 1; continue; },
                'o' => {
                    // Takes value, rest is value (known), break (fully known)
                    return false;
                },
                _ => return true,
            }
        }
        return false; // All known
    } else {
        return false; // Positional, not unknown
    }
}

