fn is_build_unknown_arg(arg: &str) -> bool {
    if arg == "--" || arg == "-" { return false; }
    if arg.starts_with("--") {
        let name = if let Some(eq) = arg.find('=') { &arg[..eq] } else { arg };
        match name {
            "--help" | "--version" | "--input" | "--outdir" => false,
            _ => true,
        }
    } else if arg.starts_with("-") && arg.len() > 1 {
        let chars: Vec<char> = arg[1..].chars().collect();
        let mut idx = 0;
        while idx < chars.len() {
            let c = chars[idx];
            match c {
                'h' | 'V' => { idx += 1; continue; },
                'i' | 'o' => { return false; }, // Takes value, rest is value, fully known
                _ => return true,
            }
        }
        return false;
    } else { false }
}

